#!/usr/bin/env node
// make-og-cards — renders one 1200×630 Open Graph card per site:
//   src/data/generated/details/*.json → public/og/sites/<domain>.png
// Run from apps/web (after fetch-data, before astro build):
//   node scripts/make-og-cards.mjs
//
// Site detail pages reference the card via ogImagePath (Base.astro falls
// back to the brand card public/og.png when the file is absent, so a build
// without this step still ships valid og:image tags). Output is gitignored —
// cards are build artifacts like dist/, regenerated by sync-site.yml.
//
// Card mirrors the report language of the site: domain, score in grade
// colour, grade ring, pending sites get the muted "—" treatment. Flat navy
// canvas + system sans via librsvg, same as make-og.mjs.
//
// Requires sharp (workspace root node_modules) + generated details.

import { readdir, mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const scriptsDir = path.dirname(fileURLToPath(import.meta.url));
const webDir = path.resolve(scriptsDir, '..');
const detailsDir = path.join(webDir, 'src', 'data', 'generated', 'details');
const outDir = path.join(webDir, 'public', 'og', 'sites');
const markPath = path.join(webDir, 'src', 'components', 'brand', 'mark.svg');

const W = 1200;
const H = 630;
const NAVY = '#0B1220';
const MINT = '#3ECFAD';
const WHITE = '#FFFFFF';
const MUTED = '#9AA4B8';
const FONT = 'DejaVu Sans, Ubuntu, sans-serif';
const GRADE_COLORS = { A: '#3ecfad', B: '#8bd450', C: '#f2c94c', D: '#f2994a', F: '#eb5757' };

const mark = await readFile(markPath, 'utf8');
const markInner = mark.match(/<svg[^>]*>([\s\S]*)<\/svg>/)?.[1];
if (!markInner) throw new Error('mark.svg: cannot find <svg> root element');

/** Escape text for SVG markup (domains are already [a-z0-9.-] but be safe). */
function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * Card SVG. Layout: mark top-left · domain (auto-shrunk, max 850px wide so
 * it never reaches the grade ring) · score row · tagline. Grade ring right.
 */
function cardSvg({ domain, score, grade }) {
  const pending = !GRADE_COLORS[grade] || typeof score !== 'number';
  const ringColor = pending ? MUTED : GRADE_COLORS[grade];
  // DejaVu Sans Bold ≈ 0.62em average advance — shrink to fit 850px.
  const domainSize = Math.max(44, Math.min(96, Math.floor(850 / (0.62 * domain.length))));
  const scoreLine = pending
    ? `<text x="64" y="470" font-family="${FONT}" font-size="88" font-weight="bold" fill="${MUTED}">Pending</text>`
    : `<text x="64" y="470" font-family="${FONT}" font-size="160" font-weight="bold" fill="${ringColor}">${score}<tspan font-size="68" font-weight="bold" fill="${MUTED}"> /100</tspan></text>`;
  const ringLetter = pending ? '—' : grade;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <rect width="${W}" height="${H}" fill="${NAVY}"/>
  <g transform="translate(64 64) scale(2.1875)">${markInner}</g>
  <text x="64" y="300" font-family="${FONT}" font-size="${domainSize}" font-weight="bold" fill="${WHITE}">${esc(domain)}</text>
  ${scoreLine}
  <text x="64" y="566" font-family="${FONT}" font-size="32" fill="${MUTED}">AI-Friendliness Rating · afr.im</text>
  <circle cx="1040" cy="380" r="110" fill="none" stroke="${ringColor}" stroke-width="12"/>
  <text x="1040" y="425" text-anchor="middle" font-family="${FONT}" font-size="120" font-weight="bold" fill="${ringColor}">${ringLetter}</text>
</svg>`;
}

const files = (await readdir(detailsDir)).filter((f) => f.endsWith('.json'));
await mkdir(outDir, { recursive: true });

let bytes = 0;
let done = 0;
const CONCURRENCY = 8;
for (let i = 0; i < files.length; i += CONCURRENCY) {
  await Promise.all(
    files.slice(i, i + CONCURRENCY).map(async (f) => {
      const detail = JSON.parse(await readFile(path.join(detailsDir, f), 'utf8'));
      const domain = detail.domain ?? f.replace(/\.json$/, '');
      const svg = cardSvg({ domain, score: detail.score, grade: detail.grade });
      const png = await sharp(Buffer.from(svg), { density: 96 })
        .resize(W, H)
        .png({ palette: true, compressionLevel: 9 })
        .toBuffer();
      await writeFile(path.join(outDir, `${domain}.png`), png);
      bytes += png.length;
      done += 1;
    }),
  );
}

console.log(
  `written ${done} cards → ${path.relative(webDir, outDir)} (${(bytes / 1024 / 1024).toFixed(1)} MB, avg ${Math.round(bytes / Math.max(done, 1))} B)`,
);
